pub fn rib_a(buf: &[u8], pos: u32, n: u32) -> u32 {
    if n == 0 || n > 32 {
        return 0;
    }
    let end = match pos.checked_add(n) {
        Some(v) => v,
        None => return 0,
    };
    if (end as u64) > (buf.len() as u64) * 8 {
        return 0;
    }

    let mut acc = 0u32;
    let mut at = pos;
    let mut left = n;
    while left != 0 {
        let room = 8 - (at % 8);
        let width = left.min(room);
        acc = (acc << width) | crate::house::rib_e(buf, at, width);
        at += width;
        left -= width;
    }
    acc
}
EOF
