use crate::pull;
use crate::tally;
use std::fs;
use std::path::Path;

pub fn rib_c() -> i32 {
    let _ = tally::lines();
    let dest = Path::new("/app/blotbay/rows.json");

    // Never leave an old result behind when this invocation cannot produce one.
    let _ = fs::remove_file(dest);
    let buf = match fs::read("/app/quaybag/night.bin") {
        Ok(v) => v,
        Err(e) => {
            eprintln!("weltquay: cannot read input: {}", e);
            return 1;
        }
    };
    if (buf.len() as u64) * 8 < pull::WIDTH_BITS as u64 {
        eprintln!(
            "weltquay: short input ({} bits; layout requires {})",
            buf.len() * 8,
            pull::WIDTH_BITS
        );
        return 1;
    }

    if let Some(parent) = dest.parent() {
        if let Err(e) = fs::create_dir_all(parent) {
            eprintln!("weltquay: cannot create output directory: {}", e);
            return 1;
        }
    }
    let (a, b, c, d, e, f) = pull::dump(&buf);
