        "{{\"kind\":{},\"lane\":{},\"mode\":{},\"welt\":{},\"tail\":{},\"mark\":{}}}\n",
        a, b, c, d, e, f
    );
    if let Err(e) = fs::write(dest, body) {
        eprintln!("weltquay: cannot write output: {}", e);
        let _ = fs::remove_file(dest);
        return 1;
    }
    0
}
